        "message.078326b85f": ["en": ["other": "This environment is not running. Launch requires a separate action and its own checks."], "ru": ["other": "Окружение не запущено. Запуск требует отдельного действия и проверок."], "uz-Latn": ["other": "Muhit ishlamayapti. Ochish uchun alohida amal va tekshiruvlar kerak."]],
        "message.091bfcfb1f": ["en": ["other": "This original profile UUID or environment is already in use. It cannot be restored twice."], "ru": ["other": "Исходный UUID профиля или окружение уже используются. Повторное восстановление запрещено."], "uz-Latn": ["other": "Asl profil UUID qiymati yoki muhit ishlatilmoqda. Ikki marta tiklash taqiqlangan."]],
        "message.0d7cf20cc5": ["en": ["other": "Managed storage already exists or is retained after an interrupted preparation. Nothing was overwritten or removed."], "ru": ["other": "Управляемое хранилище уже существует или сохранено после прерванной подготовки. Ничего не перезаписано и не удалено."], "uz-Latn": ["other": "Boshqariladigan saqlash muhiti mavjud yoki uzilgan tayyorlashdan qolgan. Hech narsa qayta yozilmadi va o‘chirilmadi."]],
        "message.0e011f9f7e": ["en": ["other": "Review Codex before continuing"], "ru": ["other": "Проверьте Codex перед продолжением"], "uz-Latn": ["other": "Davom etishdan oldin Codex ilovasini tekshiring"]],
        "message.0e257d4445": ["en": ["other": "The source account could not be verified."], "ru": ["other": "Аккаунт источника не подтверждён."], "uz-Latn": ["other": "Manba hisobi tasdiqlanmagan."]],
        "message.0ef2e8f506": ["en": ["other": "Normal exit was not confirmed within ten seconds. No force quit or target launch followed."], "ru": ["other": "Штатный выход не подтверждён за десять секунд. Принудительное закрытие и запуск цели не выполнялись."], "uz-Latn": ["other": "Oddiy chiqish o‘n soniyada tasdiqlanmadi. Majburiy yopish yoki maqsadni ochish bajarilmadi."]],
        "message.0f20c66c33": ["en": ["other": "This profile no longer exists. Refresh the list and try again."], "ru": ["other": "Профиля больше нет. Обновите список и повторите."], "uz-Latn": ["other": "Bu profil endi mavjud emas. Ro‘yxatni yangilab, qayta urinib ko‘ring."]],
        "message.0f49303465": ["en": ["other": "The usage request timed out."], "ru": ["other": "Время запроса лимитов истекло."], "uz-Latn": ["other": "Limit so‘rovi vaqti tugadi."]],
        "message.0fcfb12dfa": ["en": ["other": "Authentication required"], "ru": ["other": "Нужен вход"], "uz-Latn": ["other": "Kirish kerak"]],
        "message.10250dfdab": ["en": ["other": "Clear saved accounts?"], "ru": ["other": "Очистить сохранённые аккаунты?"], "uz-Latn": ["other": "Saqlangan hisoblar tozalansinmi?"]],
        "message.11aa986ff4": ["en": ["other": "Account verified"], "ru": ["other": "Аккаунт проверен"], "uz-Latn": ["other": "Hisob tekshirilgan"]],
        "message.11eb59c448": ["en": ["other": "Instances to close: {0}. Unrecognized instances: {1}."], "ru": ["other": "Будут закрыты: {0}. Неопознанные экземпляры: {1}."], "uz-Latn": ["other": "Yopiladigan nusxalar: {0}. Aniqlanmagan nusxalar: {1}."]],
        "message.12fb36cc76": ["en": ["other": "Window ownership cannot be confirmed. No application was activated."], "ru": ["other": "Принадлежность окна не подтверждена. Приложения не активировались."], "uz-Latn": ["other": "Oyna egaligi tasdiqlanmadi. Ilovalar faollashtirilmadi."]],
        "message.13ca412a22": ["en": ["other": "NO-GO: replacement must match an existing profile and its prepared managed environment."], "ru": ["other": "NO-GO: замена должна соответствовать существующему профилю и его подготовленному окружению."], "uz-Latn": ["other": "NO-GO: almashtirish mavjud profil va uning tayyorlangan muhitiga mos bo‘lishi kerak."]],
        "message.14d704f31c": ["en": ["other": "Account-scoped opening requires technical identity verification. Visual confirmation is insufficient."], "ru": ["other": "Открытие с подтверждением аккаунта требует технической проверки identity. Визуального подтверждения недостаточно."], "uz-Latn": ["other": "Hisobga yo‘naltirilgan ochish texnik identity tekshiruvini talab qiladi. Vizual tasdiq yetarli emas."]],
        "message.166c987ae9": ["en": ["other": "Account setup recovered. No Codex data or processes were changed."], "ru": ["other": "Настройка аккаунтов восстановлена. Данные и процессы Codex не изменялись."], "uz-Latn": ["other": "Hisoblar sozlashi tiklandi. Codex ma’lumotlari va jarayonlari o‘zgarmadi."]],
        "message.177d857991": ["en": ["other": "Activity: Unknown (Desktop status connection unverified; confirmation required for every switch)"], "ru": ["other": "Активность: неизвестна (соединение статуса Desktop не подтверждено; каждое переключение требует подтверждения)"], "uz-Latn": ["other": "Faollik: noma’lum (Desktop holat ulanishi tasdiqlanmagan; har bir almashish tasdiq talab qiladi)"]],
        "message.18b6768fd3": ["en": ["other": "Codex instance ownership is ambiguous. No unknown instance will be closed."], "ru": ["other": "Принадлежность экземпляра Codex неоднозначна. Неизвестные экземпляры закрываться не будут."], "uz-Latn": ["other": "Codex nusxasining egaligi noaniq. Noma’lum nusxalar yopilmaydi."]],
        "message.193149e5c0": ["en": ["other": "The selected Codex instance changed. The operation stopped."], "ru": ["other": "Выбранный экземпляр Codex изменился. Операция остановлена."], "uz-Latn": ["other": "Tanlangan Codex nusxasi o‘zgardi. Amal to‘xtatildi."]],
        "message.1c0410c771": ["en": ["other": "Allow closing “{0}”"], "ru": ["other": "Разрешаю закрыть «{0}»"], "uz-Latn": ["other": "“{0}” hisobini yopishga ruxsat beraman"]],
        "message.1da138e845": ["en": ["other": "Detected tasks: {0} (local: {1}, cloud: {2}, execution location unknown: {3})."], "ru": ["other": "Обнаружено задач: {0} (локальных: {1}, облачных: {2}, место выполнения неизвестно: {3})."], "uz-Latn": ["other": "Topilgan vazifalar: {0} (mahalliy: {1}, bulutda: {2}, bajarilish joyi noma’lum: {3})."]],
        "message.1e8e229013": ["en": ["other": "Review Interrupted Account Setup"], "ru": ["other": "Проверить прерванную настройку аккаунтов"], "uz-Latn": ["other": "Uzilgan hisob sozlashini tekshirish"]],
        "message.2185869f0b": ["en": ["other": "Local execution may stop when Codex closes. Cloud execution has a different interruption risk; its continuation is not guaranteed."], "ru": ["other": "Локальное выполнение может остановиться при закрытии Codex. Риск прерывания облачных задач отличается; их продолжение не гарантировано."], "uz-Latn": ["other": "Codex yopilganda mahalliy bajarilish to‘xtashi mumkin. Bulutdagi ishning to‘xtash xavfi boshqacha; davom etishi kafolatlanmaydi."]],
        "message.2444bd5ab3": ["en": ["other": "Environment linked"], "ru": ["other": "Окружение привязано"], "uz-Latn": ["other": "Muhit bog‘langan"]],
        "message.24d9bda6f8": ["en": ["other": "An account profile with this name already exists."], "ru": ["other": "Профиль аккаунта с таким названием уже существует."], "uz-Latn": ["other": "Bu nomli hisob profili mavjud."]],
        "message.275e5420ee": ["en": ["other": "Some instances closed, but the operation did not complete. Review them manually; no automatic restoration was attempted."], "ru": ["other": "Некоторые экземпляры закрылись, но операция не завершилась. Проверьте их вручную; автоматического восстановления не было."], "uz-Latn": ["other": "Ayrim nusxalar yopildi, lekin amal tugamadi. Ularni qo‘lda tekshiring; avtomatik tiklash bajarilmadi."]],
        "message.287b34a6b0": ["en": ["other": "Choose Codex Application"], "ru": ["other": "Выбрать приложение Codex"], "uz-Latn": ["other": "Codex ilovasini tanlash"]],
        "message.2975132481": ["en": ["other": "Weekly"], "ru": ["other": "За неделю"], "uz-Latn": ["other": "Haftalik"]],
        "message.2a0870a04d": ["en": ["other": "Activate its Codex instance or launch its linked environment"], "ru": ["other": "Активировать экземпляр Codex или запустить привязанное окружение"], "uz-Latn": ["other": "Codex nusxasini faollashtirish yoki bog‘langan muhitni ochish"]],
        "message.2aa0810102": ["en": ["other": "Activity status: Unknown. Check Codex before continuing. The status will be checked again before Codex is closed."], "ru": ["other": "Состояние активности: неизвестно. Проверьте Codex перед продолжением. Перед закрытием состояние будет проверено снова."], "uz-Latn": ["other": "Faollik holati: noma’lum. Davom etishdan oldin Codex ilovasini tekshiring. Yopishdan oldin holat yana tekshiriladi."]],
        "message.2b5386b862": ["en": ["other": "The selected account could not be opened. No automatic retry was attempted."], "ru": ["other": "Не удалось открыть выбранный аккаунт. Автоматический повтор не выполнялся."], "uz-Latn": ["other": "Tanlangan hisobni ochib bo‘lmadi. Avtomatik qayta urinish bajarilmadi."]],
        "message.2c23be5fbf": ["en": ["other": "Additional · {0}"], "ru": ["other": "Дополнительно · {0}"], "uz-Latn": ["other": "Qo‘shimcha · {0}"]],
        "message.2d9efee894": ["en": ["other": "The profile storage location is unsafe. Symbolic links are not supported."], "ru": ["other": "Небезопасное расположение хранилища. Символические ссылки не поддерживаются."], "uz-Latn": ["other": "Profil saqlash joyi xavfsiz emas. Ramziy havolalar qo‘llab-quvvatlanmaydi."]],
        "message.2f22292713": ["en": ["other": "Normal termination could not be confirmed. Review the existing instance."], "ru": ["other": "Штатное закрытие не подтверждено. Проверьте работающий экземпляр."], "uz-Latn": ["other": "Oddiy yopish tasdiqlanmadi. Ishlayotgan nusxani tekshiring."]],
        "message.2f996d867a": ["en": ["other": "Remove Profile"], "ru": ["other": "Удалить профиль"], "uz-Latn": ["other": "Profilni olib tashlash"]],
        "message.30d80dc546": ["en": ["other": "Application recovery requires your review. All environment data has been retained."], "ru": ["other": "Восстановление требует вашей проверки. Все данные окружения сохранены."], "uz-Latn": ["other": "Tiklash uchun tekshiruvingiz kerak. Muhitning barcha ma’lumotlari saqlandi."]],
        "message.3100fee388": ["en": ["other": "A Codex instance changed. Review the current instances before trying again."], "ru": ["other": "Экземпляр Codex изменился. Проверьте текущие экземпляры перед повтором."], "uz-Latn": ["other": "Codex nusxasi o‘zgardi. Qayta urinishdan oldin joriy nusxalarni tekshiring."]],
        "message.311398edea": ["en": ["other": "The usage service is unavailable."], "ru": ["other": "Сервис лимитов недоступен."], "uz-Latn": ["other": "Limit xizmati mavjud emas."]],
        "message.314e6d47e7": ["en": ["other": "Codex launch could not be confirmed. No automatic retry was attempted."], "ru": ["other": "Запуск Codex не подтверждён. Автоматический повтор не выполнялся."], "uz-Latn": ["other": "Codex ochilishi tasdiqlanmadi. Avtomatik qayta urinish bajarilmadi."]],
        "message.327af4e2b1": ["en": ["other": "Activate the existing Codex instance (PID {0})."], "ru": ["other": "Активировать существующий экземпляр Codex (PID {0})."], "uz-Latn": ["other": "Mavjud Codex nusxasini faollashtirish (PID {0})."]],
        "message.36be42b4fd": ["en": ["other": "Accessibility permission is required to address the confirmed window. No permission request was made."], "ru": ["other": "Для обращения к подтверждённому окну нужно разрешение Универсального доступа. Запрос разрешения не выполнялся."], "uz-Latn": ["other": "Tasdiqlangan oynaga murojaat qilish uchun Maxsus imkoniyatlar ruxsati kerak. Ruxsat so‘ralmadi."]],
        "message.3a5cedce65": ["en": ["other": "Task activity is unknown. Explicit interruption confirmation is required."], "ru": ["other": "Активность задач неизвестна. Нужно явное подтверждение прерывания."], "uz-Latn": ["other": "Vazifa faolligi noma’lum. To‘xtatishga aniq tasdiq kerak."]],
        "message.3b037284c5": ["en": ["other": "Account setup mode"], "ru": ["other": "Способ добавления аккаунта"], "uz-Latn": ["other": "Hisob qo‘shish usuli"]],
        "message.3b862eee81": ["en": ["other": "Review the previous result before another operation."], "ru": ["other": "Перед новой операцией проверьте предыдущий результат."], "uz-Latn": ["other": "Yangi amaldan oldin oldingi natijani tekshiring."]],
        "message.3d3016d2b1": ["en": ["other": "I understand: only saved records will be removed; active profiles and Codex data will stay."], "ru": ["other": "Я понимаю: удалятся только сохранённые записи; активные профили и данные Codex сохранятся."], "uz-Latn": ["other": "Tushunaman: faqat saqlangan yozuvlar o‘chiriladi; faol profillar va Codex ma’lumotlari saqlanadi."]],
        "message.3eebcc98bb": ["en": ["other": "% left"], "ru": ["other": "% осталось"], "uz-Latn": ["other": "% qoldi"]],
        "message.4088b2673d": ["en": ["other": "Confirm clearing saved account records"], "ru": ["other": "Подтвердить очистку сохранённых записей аккаунтов"], "uz-Latn": ["other": "Saqlangan hisob yozuvlarini tozalashni tasdiqlash"]],
        "message.410984c2e3": ["en": ["other": "Codex activity kept changing. The operation stopped before interruption."], "ru": ["other": "Активность Codex продолжала меняться. Операция остановлена до прерывания."], "uz-Latn": ["other": "Codex faolligi o‘zgarishda davom etdi. Amal to‘xtatishdan oldin to‘xtadi."]],
        "message.426f610b55": ["en": ["other": "A verified setup backup could not be created. No active metadata was changed."], "ru": ["other": "Не удалось создать проверенную копию настройки. Активные метаданные не менялись."], "uz-Latn": ["other": "Sozlashning tekshirilgan zaxirasini yaratib bo‘lmadi. Faol metama’lumot o‘zgarmadi."]],
        "message.438dd16a76": ["en": ["other": "Sign-in is required in the official app."], "ru": ["other": "Войдите в официальном приложении."], "uz-Latn": ["other": "Rasmiy ilovada kiring."]],
        "message.4479980b60": ["en": ["other": "Environment opening: available through per-operation GUI confirmation; technical identity and Usage remain unverified"], "ru": ["other": "Открытие окружений: доступно с отдельным подтверждением каждой операции; техническая identity и лимиты не подтверждены"], "uz-Latn": ["other": "Muhitlarni ochish: har bir amalni alohida tasdiqlash bilan mavjud; texnik identity va limitlar tasdiqlanmagan"]],
        "message.4585bf8efa": ["en": ["other": "Verification required"], "ru": ["other": "Нужна проверка"], "uz-Latn": ["other": "Tekshirish kerak"]],
        "message.46c6de9805": ["en": ["other": "CodexSwoop cannot verify whether Codex has unfinished tasks. Switching accounts may interrupt their execution. Are you sure you want to continue?"], "ru": ["other": "CodexSwoop не может проверить, есть ли у Codex незавершённые задачи. Переключение аккаунта может прервать их. Продолжить?"], "uz-Latn": ["other": "CodexSwoop Codex ilovasida tugamagan vazifalar borligini tekshira olmaydi. Hisobni almashtirish ularni to‘xtatishi mumkin. Davom etilsinmi?"]],
        "message.476470c77c": ["en": ["other": "Profile removed. Its Codex environment and authorization remain on disk."], "ru": ["other": "Профиль удалён. Окружение Codex и авторизация сохранены на диске."], "uz-Latn": ["other": "Profil olib tashlandi. Codex muhiti va kirish holati diskda saqlandi."]],
        "message.47c40f7547": ["en": ["other": "Open Separately"], "ru": ["other": "Открыть отдельно"], "uz-Latn": ["other": "Alohida ochish"]],
        "message.47d20f9886": ["en": ["other": "Usage data is unavailable."], "ru": ["other": "Данные лимитов недоступны."], "uz-Latn": ["other": "Limit ma’lumotlari mavjud emas."]],
        "message.4ce4ee0d33": ["en": ["other": "Temporary research data can be removed by macOS. Linking does not make it durable or move any files."], "ru": ["other": "macOS может удалить временные исследовательские данные. Привязка не сохраняет и не перемещает файлы."], "uz-Latn": ["other": "macOS vaqtinchalik tadqiqot ma’lumotlarini o‘chirishi mumkin. Bog‘lash fayllarni doimiy saqlamaydi va ko‘chirmaydi."]],
        "message.4e774de9dc": ["en": ["other": "Credential-store isolation has not been established for this operation."], "ru": ["other": "Изоляция хранилища учётных данных для этой операции не подтверждена."], "uz-Latn": ["other": "Bu amal uchun kirish ma’lumotlari saqlash joyining ajratilishi tasdiqlanmagan."]],
        "message.4ead23a313": ["en": ["other": "Opens the environment associated with this profile. ChatGPT account identity has not been independently verified."], "ru": ["other": "Открывает окружение этого профиля. Identity аккаунта ChatGPT независимо не подтверждена."], "uz-Latn": ["other": "Shu profil muhitini ochadi. ChatGPT hisobi identity qiymati mustaqil tasdiqlanmagan."]],
        "message.4f1a31a200": ["en": ["other": "Profile storage is unavailable. Check disk space and folder permissions."], "ru": ["other": "Хранилище профилей недоступно. Проверьте место на диске и права каталога."], "uz-Latn": ["other": "Profil saqlash joyi mavjud emas. Diskdagi joy va papka ruxsatlarini tekshiring."]],
        "message.4fe12ddf22": ["en": ["other": "The one-shot trial is retired. Open CodexSwoop normally and choose an account action; every action requires fresh checks and confirmation."], "ru": ["other": "Одноразовый тест отключён. Откройте CodexSwoop обычным способом и выберите действие аккаунта; каждая операция требует свежих проверок и подтверждения."], "uz-Latn": ["other": "Bir martalik sinov o‘chirilgan. CodexSwoop ilovasini odatdagidek ochib, hisob amalini tanlang; har bir amal yangi tekshiruv va tasdiq talab qiladi."]],
        "message.527713b41f": ["en": ["other": "Account identity cannot be verified. Linking directories does not confirm sign-in."], "ru": ["other": "Identity аккаунта не подтверждена. Привязка каталогов не подтверждает вход."], "uz-Latn": ["other": "Hisob identity qiymati tasdiqlanmagan. Papkalarni bog‘lash kirishni tasdiqlamaydi."]],
        "message.53980467fa": ["en": ["other": "Switch Anyway"], "ru": ["other": "Всё равно переключить"], "uz-Latn": ["other": "Baribir almashtirish"]],
        "message.53e2b9f9d3": ["en": ["other": "Environment to keep open: {0}."], "ru": ["other": "Оставить открытым окружение: {0}."], "uz-Latn": ["other": "Ochiq qoldiriladigan muhit: {0}."]],
        "message.543aeaca22": ["en": ["other": "An action may have taken effect. Review Codex before another operation; no automatic recovery was attempted."], "ru": ["other": "Запрос мог выполниться. Перед новой операцией проверьте Codex; автоматическое восстановление не выполнялось."], "uz-Latn": ["other": "So‘rov bajarilgan bo‘lishi mumkin. Yangi amaldan oldin Codex ilovasini tekshiring; avtomatik tiklash bajarilmadi."]],
        "message.547855e3a8": ["en": ["other": "This environment or one of its directories is already linked to a profile."], "ru": ["other": "Окружение или один из его каталогов уже привязаны к профилю."], "uz-Latn": ["other": "Muhit yoki uning papkalaridan biri allaqachon profilga bog‘langan."]],
        "message.54a0e8c17e": ["en": ["other": "Error"], "ru": ["other": "Ошибка"], "uz-Latn": ["other": "Xato"]],
        "message.54dbf3f981": ["en": ["other": "A unique Codex instance could not be associated with the environment. No application was closed."], "ru": ["other": "Не удалось однозначно сопоставить экземпляр Codex с окружением. Приложения не закрывались."], "uz-Latn": ["other": "Codex nusxasini muhitga aniq moslab bo‘lmadi. Ilovalar yopilmadi."]],
        "message.5638c9c401": ["en": ["other": "Saving changes CodexSwoop reference metadata only. Your profile UUID and Codex data stay the same."], "ru": ["other": "Сохраняются только метаданные привязки CodexSwoop. UUID профиля и данные Codex остаются прежними."], "uz-Latn": ["other": "Faqat CodexSwoop bog‘lanish metama’lumoti saqlanadi. Profil UUID qiymati va Codex ma’lumotlari o‘zgarmaydi."]],
        "message.56e563ef71": ["en": ["other": "Confirmed closed: "], "ru": ["other": "Подтверждено закрытие: "], "uz-Latn": ["other": "Yopilishi tasdiqlangan: "]],
        "message.57ce189a39": ["en": ["other": "Choose the original supported environment directories. Paths must be absolute and canonical."], "ru": ["other": "Выберите исходные поддерживаемые каталоги окружения. Пути должны быть абсолютными и каноническими."], "uz-Latn": ["other": "Asl qo‘llab-quvvatlanadigan muhit papkalarini tanlang. Yo‘llar mutlaq va kanonik bo‘lishi kerak."]],
        "message.5827ce9e93": ["en": ["other": "Create a fresh isolated environment with its own UUID. Then choose Open Separately and Sign In in official Codex yourself. Authorization is never copied."], "ru": ["other": "Создать новое изолированное окружение с собственным UUID. Затем выберите «Открыть отдельно» и войдите через официальный Sign In в Codex. Авторизация не копируется."], "uz-Latn": ["other": "O‘z UUID qiymatiga ega yangi ajratilgan muhit yarating. Keyin «Alohida ochish»ni tanlab, rasmiy Codex Sign In orqali kiring. Kirish ma’lumotlari nusxalanmaydi."]],
        "message.59e231637b": ["en": ["other": "Reserve A · retained research environment"], "ru": ["other": "Резервное A · сохранённое исследовательское окружение"], "uz-Latn": ["other": "Zaxira A · saqlangan tadqiqot muhiti"]],
        "message.5a767395c3": ["en": ["other": "\n\nBrings the existing Codex instance forward. A specific window is not selected."], "ru": ["other": "\n\nВыводит существующий экземпляр Codex вперёд. Конкретное окно не выбирается."], "uz-Latn": ["other": "\n\nMavjud Codex nusxasini oldinga chiqaradi. Alohida oyna tanlanmaydi."]],
        "message.5b12ebbdb3": ["en": ["other": "Live usage is disabled. A supported, account-verified transport needs separate approval."], "ru": ["other": "Живые лимиты отключены. Нужны поддерживаемое соединение с подтверждённым аккаунтом и отдельное разрешение."], "uz-Latn": ["other": "Jonli limitlar o‘chirilgan. Hisobi tasdiqlangan qo‘llab-quvvatlanadigan ulanish va alohida ruxsat kerak."]],
        "message.5ed251166f": ["en": ["other": "A unique owned window is unavailable. No alternative window or launch was selected."], "ru": ["other": "Однозначно принадлежащее окно недоступно. Другое окно и запуск не выбирались."], "uz-Latn": ["other": "Egasi aniq oyna mavjud emas. Boshqa oyna yoki ochish tanlanmadi."]],
        "message.60100daa61": ["en": ["other": "Link Environment"], "ru": ["other": "Привязать окружение"], "uz-Latn": ["other": "Muhitni bog‘lash"]],
        "message.60717ca80a": ["en": ["other": "Accessibility permission is missing. No system permission request was made."], "ru": ["other": "Нет разрешения Универсального доступа. Системный запрос разрешения не выполнялся."], "uz-Latn": ["other": "Maxsus imkoniyatlar ruxsati yo‘q. Tizim ruxsat so‘rovi yuborilmadi."]],
        "message.60b621bd7e": ["en": ["other": "This may interrupt running tasks and unsaved work."], "ru": ["other": "Это может прервать работающие задачи и несохранённую работу."], "uz-Latn": ["other": "Bu ishlayotgan vazifalar va saqlanmagan ishlarni to‘xtatishi mumkin."]],
        "message.63b8a0d3a4": ["en": ["other": "macOS: {0}"], "ru": ["other": "macOS: {0}"], "uz-Latn": ["other": "macOS: {0}"]],
        "message.6527e566f5": ["en": ["other": "The source supplied no quota windows."], "ru": ["other": "Источник не предоставил интервалы лимитов."], "uz-Latn": ["other": "Manba limit davrlarini taqdim etmadi."]],
        "message.66b08526db": ["en": ["other": "Awaiting your approval: {0}. Awaiting your input: {1}. Background processes: {2}."], "ru": ["other": "Ожидают вашего разрешения: {0}. Ожидают ввода: {1}. Фоновых процессов: {2}."], "uz-Latn": ["other": "Ruxsatingizni kutmoqda: {0}. Kiritishni kutmoqda: {1}. Fon jarayonlari: {2}."]],
        "message.68b9f4aa0d": ["en": ["other": "Local profiles: unavailable"], "ru": ["other": "Локальные профили: недоступны"], "uz-Latn": ["other": "Mahalliy profillar: mavjud emas"]],
        "message.6910fb9db8": ["en": ["other": "Account identity user-confirmed. Independent technical verification is unavailable."], "ru": ["other": "Аккаунт подтверждён пользователем. Независимая техническая проверка недоступна."], "uz-Latn": ["other": "Hisob foydalanuvchi tomonidan tasdiqlandi. Mustaqil texnik tekshiruv mavjud emas."]],
        "message.6ac8869344": ["en": ["other": "Close other Codex instances?"], "ru": ["other": "Закрыть остальные экземпляры Codex?"], "uz-Latn": ["other": "Boshqa Codex nusxalari yopilsinmi?"]],
        "message.6b537cf877": ["en": ["other": "Account setup changed. Review the current profiles and confirm a fresh operation."], "ru": ["other": "Настройка аккаунтов изменилась. Проверьте текущие профили и подтвердите новую операцию."], "uz-Latn": ["other": "Hisoblar sozlashi o‘zgardi. Joriy profillarni tekshirib, yangi amalni tasdiqlang."]],
        "message.6bbc80c8c4": ["en": ["other": "The verified account does not match this profile. The operation stopped."], "ru": ["other": "Проверенный аккаунт не соответствует профилю. Операция остановлена."], "uz-Latn": ["other": "Tekshirilgan hisob profilga mos emas. Amal to‘xtatildi."]],
        "message.6cd2894127": ["en": ["other": "Metadata outcome requires read-only review. Do not retry or restore automatically."], "ru": ["other": "Результат записи метаданных требует проверки только чтением. Не повторяйте и не восстанавливайте автоматически."], "uz-Latn": ["other": "Metama’lumot yozish natijasini faqat o‘qish orqali tekshirish kerak. Avtomatik takrorlamang yoki tiklamang."]],
        "message.6eb284eb36": ["en": ["other": "The reviewed official Codex application is unavailable."], "ru": ["other": "Проверенное официальное приложение Codex недоступно."], "uz-Latn": ["other": "Tekshirilgan rasmiy Codex ilovasi mavjud emas."]],
        "message.70746949bd": ["en": ["other": "Launch at login could not be changed. Install CodexSwoop in Applications and check Login Items in System Settings."], "ru": ["other": "Не удалось изменить запуск при входе. Установите CodexSwoop в Applications и проверьте объекты входа в Системных настройках."], "uz-Latn": ["other": "Tizimga kirishda ochishni o‘zgartirib bo‘lmadi. CodexSwoop ilovasini Applications ichiga o‘rnating va System Settings ichidagi Login Items bo‘limini tekshiring."]],
        "message.7280996b1a": ["en": ["other": "The requested Codex instance could not be confirmed in the foreground. No retry or restart was attempted."], "ru": ["other": "Запрошенный экземпляр Codex не подтверждён на переднем плане. Повтор и перезапуск не выполнялись."], "uz-Latn": ["other": "So‘ralgan Codex nusxasi oldingi planda tasdiqlanmadi. Qayta urinish yoki qayta ochish bajarilmadi."]],
        "message.72ae99f8b5": ["en": ["other": "Profile metadata is damaged. Changes are blocked to protect your data."], "ru": ["other": "Метаданные профилей повреждены. Изменения заблокированы для защиты данных."], "uz-Latn": ["other": "Profil metama’lumoti buzilgan. Ma’lumotlarni himoyalash uchun o‘zgarishlar bloklandi."]],
        "message.7325c9a51a": ["en": ["other": "Allow CodexSwoop in System Settings → General → Login Items."], "ru": ["other": "Разрешите CodexSwoop в Системных настройках → Основные → Объекты входа."], "uz-Latn": ["other": "Tizim sozlamalari → Umumiy → Kirish obyektlari orqali CodexSwoop ilovasiga ruxsat bering."]],
        "message.732ecec0b2": ["en": ["other": "Codex did not finish exiting within ten seconds. No force quit or restart was attempted."], "ru": ["other": "Codex не завершил выход за десять секунд. Принудительное закрытие и перезапуск не выполнялись."], "uz-Latn": ["other": "Codex o‘n soniyada chiqmadi. Majburiy yopish yoki qayta ochish bajarilmadi."]],
        "message.76263ac694": ["en": ["other": "Environment ownership, permissions or symbolic links are unsafe. Nothing was changed."], "ru": ["other": "Небезопасные владелец, права или символические ссылки окружения. Изменений нет."], "uz-Latn": ["other": "Muhit egasi, ruxsatlari yoki ramziy havolalari xavfsiz emas. Hech narsa o‘zgarmadi."]],
        "message.76aa43e568": ["en": ["other": "Codex version: {0}"], "ru": ["other": "Версия Codex: {0}"], "uz-Latn": ["other": "Codex versiyasi: {0}"]],
        "message.7988b44076": ["en": ["other": "I reviewed Codex"], "ru": ["other": "Codex проверен мной"], "uz-Latn": ["other": "Codex ilovasini tekshirdim"]],
        "message.79df49e4c0": ["en": ["other": "Menu bar icon: {0}"], "ru": ["other": "Иконка строки меню: {0}"], "uz-Latn": ["other": "Menyu satri belgisi: {0}"]],
        "message.7bdf731db2": ["en": ["other": "An account operation is in progress."], "ru": ["other": "Выполняется операция с аккаунтом."], "uz-Latn": ["other": "Hisob bilan amal bajarilmoqda."]],
        "message.7c00126505": ["en": ["other": "Previous result reviewed. Choose an account to start a fresh operation."], "ru": ["other": "Предыдущий результат проверен. Выберите аккаунт для новой операции."], "uz-Latn": ["other": "Oldingi natija tekshirildi. Yangi amal uchun hisobni tanlang."]],
        "message.7fcd27f57c": ["en": ["other": "Ready. Choose Open Separately, then sign in through Codex."], "ru": ["other": "Готово. Выберите «Открыть отдельно», затем войдите в Codex."], "uz-Latn": ["other": "Tayyor. Alohida ochishni tanlang, keyin Codex orqali kiring."]],
        "message.80fbafe4c9": ["en": ["other": "Backup failed. No association replacement was committed."], "ru": ["other": "Резервное копирование не удалось. Замена привязки не сохранена."], "uz-Latn": ["other": "Zaxiralash bajarilmadi. Bog‘lanishni almashtirish saqlanmadi."]],
        "message.82268712b8": ["en": ["other": "The saved environment does not match its original UUID, directories or supported format. Nothing was moved or imported."], "ru": ["other": "Сохранённое окружение не соответствует исходному UUID, каталогам или формату. Ничего не перемещено и не импортировано."], "uz-Latn": ["other": "Saqlangan muhit asl UUID, papkalar yoki formatga mos emas. Hech narsa ko‘chirilmadi va import qilinmadi."]],
        "message.8306c1732d": ["en": ["other": "Empty permanent storage prepared. No account is linked or signed in; official enrollment needs separate approval."], "ru": ["other": "Пустое постоянное хранилище подготовлено. Аккаунт не привязан, вход не выполнен; официальную авторизацию пользователь проходит отдельно."], "uz-Latn": ["other": "Bo‘sh doimiy saqlash muhiti tayyorlandi. Hisob bog‘lanmagan, kirilmagan; rasmiy kirishni foydalanuvchi alohida bajaradi."]],
        "message.8598a8cfdb": ["en": ["other": "Directories checked. Authorization and effective running configuration remain unverified."], "ru": ["other": "Каталоги проверены. Авторизация и фактические настройки работающего экземпляра не подтверждены."], "uz-Latn": ["other": "Papkalar tekshirildi. Kirish holati va ishlayotgan nusxaning haqiqiy sozlamalari tasdiqlanmagan."]],
        "message.85bed1aa51": ["en": ["other": "The account operation failed. Existing data was retained; review the application state."], "ru": ["other": "Операция с аккаунтом не удалась. Данные сохранены; проверьте состояние приложения."], "uz-Latn": ["other": "Hisob amali bajarilmadi. Ma’lumotlar saqlandi; ilova holatini tekshiring."]],
        "message.86d7fe1e18": ["en": ["other": "Another account operation is in progress."], "ru": ["other": "Выполняется другая операция с аккаунтом."], "uz-Latn": ["other": "Hisob bilan boshqa amal bajarilmoqda."]],
        "message.87ac78e2c2": ["en": ["other": "Codex has unfinished tasks. Switching accounts may interrupt their execution. Are you sure you want to continue?"], "ru": ["other": "В Codex есть незавершённые задачи. Переключение аккаунта может прервать их. Продолжить?"], "uz-Latn": ["other": "Codex ilovasida tugamagan vazifalar bor. Hisobni almashtirish ularni to‘xtatishi mumkin. Davom etilsinmi?"]],
        "message.89787c9311": ["en": ["other": "Saved environment restored with its original profile UUID. No Codex files were moved."], "ru": ["other": "Окружение восстановлено с исходным UUID профиля. Файлы Codex не перемещались."], "uz-Latn": ["other": "Muhit asl profil UUID qiymati bilan tiklandi. Codex fayllari ko‘chirilmadi."]],
        "message.8a58f94ff3": ["en": ["other": "Coverage is incomplete; additional operations may exist."], "ru": ["other": "Проверка охватывает не всё; возможны дополнительные операции."], "uz-Latn": ["other": "Tekshiruv to‘liq qamramaydi; qo‘shimcha amallar mavjud bo‘lishi mumkin."]],
        "message.8b95130155": ["en": ["other": "The source returned invalid usage data."], "ru": ["other": "Источник вернул некорректные данные лимитов."], "uz-Latn": ["other": "Manba noto‘g‘ri limit ma’lumotini qaytardi."]],
        "message.8ca62aa4f2": ["en": ["other": "Codex signature or installation evidence could not be verified, or the installation changed during this operation. No version allowlist is required."], "ru": ["other": "Не удалось проверить подпись или установку Codex, либо установка изменилась во время операции. Список разрешённых версий не требуется."], "uz-Latn": ["other": "Codex imzosi yoki o‘rnatma dalillarini tasdiqlab bo‘lmadi yoki o‘rnatma amal davomida o‘zgardi. Versiyalar ruxsat ro‘yxati talab qilinmaydi."]],
        "message.8cad1ab7dd": ["en": ["other": "Link an environment to this profile first."], "ru": ["other": "Сначала привяжите окружение к этому профилю."], "uz-Latn": ["other": "Avval bu profilga muhit bog‘lang."]],
        "message.90366fe7c8": ["en": ["other": "The reviewed official Codex application is unavailable. No alternative application was launched."], "ru": ["other": "Проверенное официальное приложение Codex недоступно. Другое приложение не запускалось."], "uz-Latn": ["other": "Tekshirilgan rasmiy Codex ilovasi mavjud emas. Boshqa ilova ochilmadi."]],
        "message.91b956370c": ["en": ["other": "Confirm this specific environment before opening it."], "ru": ["other": "Подтвердите открытие именно этого окружения."], "uz-Latn": ["other": "Aynan shu muhitni ochishni tasdiqlang."]],
        "message.9234069589": ["en": ["other": "Active"], "ru": ["other": "Активен"], "uz-Latn": ["other": "Faol"]],
        "message.923b5dcf1c": ["en": ["other": "No valid metadata backup is available. Your existing files have been preserved."], "ru": ["other": "Корректной копии метаданных нет. Существующие файлы сохранены."], "uz-Latn": ["other": "Yaroqli metama’lumot zaxirasi yo‘q. Mavjud fayllar saqlandi."]],
        "message.92d6637423": ["en": ["other": "Profile or environment metadata is unavailable."], "ru": ["other": "Метаданные профиля или окружения недоступны."], "uz-Latn": ["other": "Profil yoki muhit metama’lumoti mavjud emas."]],
        "message.93e95e0c73": ["en": ["other": "Switching is blocked until account identity and two-account integration are verified."], "ru": ["other": "Переключение заблокировано до подтверждения identity аккаунта и интеграции двух аккаунтов."], "uz-Latn": ["other": "Hisob identity qiymati va ikki hisob integratsiyasi tasdiqlanmaguncha almashish bloklangan."]],
        "message.944d592a28": ["en": ["other": "The operation could not be completed. Your existing data has been preserved."], "ru": ["other": "Не удалось завершить операцию. Существующие данные сохранены."], "uz-Latn": ["other": "Amalni tugatib bo‘lmadi. Mavjud ma’lumotlar saqlandi."]],
        "message.958a2bd790": ["en": ["other": "Environment activation awaits a separately approved activation-only trial."], "ru": ["other": "Активация окружения ожидает отдельно разрешённого теста только активации."], "uz-Latn": ["other": "Muhitni faollashtirish alohida ruxsat etilgan faollashtirish sinovini kutmoqda."]],
        "message.9611212cdd": ["en": ["other": "The environment changed since verification. Review and link it again; automatic repair is unavailable."], "ru": ["other": "Окружение изменилось после проверки. Проверьте и привяжите заново; автоматическое исправление недоступно."], "uz-Latn": ["other": "Muhit tekshiruvdan keyin o‘zgardi. Ko‘rib chiqib, qayta bog‘lang; avtomatik tuzatish mavjud emas."]],
        "message.96d15cf84b": ["en": ["other": "{0} min"], "ru": ["other": "{0} мин"], "uz-Latn": ["other": "{0} daq"]],
        "message.9d592c131b": ["en": ["other": "A {0} operation did not finish. The verified backup and current files will be checked before recovery.\n\nFinish the reviewed change or restore the complete previous metadata set. Codex files and running instances remain untouched."], "ru": ["other": "Операция {0} не завершилась. Перед восстановлением будут проверены резервная копия и текущие файлы.\n\nЗавершите согласованное изменение или восстановите весь предыдущий набор метаданных. Файлы Codex и работающие экземпляры сохранятся."], "uz-Latn": ["other": "{0} amali tugamadi. Tiklashdan oldin zaxira va joriy fayllar tekshiriladi.\n\nKo‘rib chiqilgan o‘zgarishni tugating yoki oldingi metama’lumot to‘plamini to‘liq tiklang. Codex fayllari va ishlayotgan nusxalar saqlanadi."]],
        "message.9fffb9bda0": ["en": ["other": "CodexSwoop: {0}"], "ru": ["other": "CodexSwoop: {0}"], "uz-Latn": ["other": "CodexSwoop: {0}"]],
        "message.a0eca2612a": ["en": ["other": "Saved account list cleared. Active profiles are unchanged."], "ru": ["other": "Список сохранённых аккаунтов очищен. Активные профили сохранены."], "uz-Latn": ["other": "Saqlangan hisoblar ro‘yxati tozalandi. Faol profillar saqlandi."]],
        "message.a2e174d314": ["en": ["other": "Disconnect the environment before removing this profile. Environment data will be retained."], "ru": ["other": "Перед удалением профиля отключите окружение. Данные окружения сохранятся."], "uz-Latn": ["other": "Profilni olib tashlashdan oldin muhitni ajrating. Muhit ma’lumotlari saqlanadi."]],
        "message.a7f4e51df7": ["en": ["other": "Close Others is blocked: a Codex instance has no unique registered environment owner (possibly retained reserve A or another app copy). Its PID, generation, signature and both directory roots must be attributable. A retained backup reference is accepted only after fresh marker, directory and live process checks; a historical PID cannot authorize closing it. Review and close it manually if intended. Open Separately remains available."], "ru": ["other": "Закрытие остальных заблокировано: экземпляр Codex не имеет однозначного зарегистрированного владельца окружения (возможно, резервное A или другая копия приложения). Нужны проверенные PID, поколение, подпись и оба каталога. Сохранённая привязка принимается только после свежих проверок маркера, каталогов и процессов; старый PID не разрешает закрытие. Проверьте и при необходимости закройте экземпляр вручную. «Открыть отдельно» остаётся доступным."], "uz-Latn": ["other": "Boshqalarini yopish bloklandi: Codex nusxasining ro‘yxatdan o‘tgan muhit egasi aniq emas (zaxira A yoki ilovaning boshqa nusxasi bo‘lishi mumkin). PID, avlod, imzo va ikkala papka tekshirilishi kerak. Saqlangan bog‘lanish faqat marker, papkalar va jarayonlar qayta tekshirilgach qabul qilinadi; eski PID yopishga ruxsat bermaydi. Tekshirib, kerak bo‘lsa nusxani qo‘lda yoping. «Alohida ochish» mavjud qoladi."]],
        "message.a80bbaae71": ["en": ["other": "Remove {0} saved account records from this list. Active profiles and their links stay unchanged.\n\nA verified metadata backup will be created first. Codex environments, sign-in, projects, history and running instances are preserved."], "ru": ["other": "Удалить сохранённые записи аккаунтов ({0}) из этого списка. Активные профили и их привязки не изменятся.\n\nСначала будет создана проверенная резервная копия метаданных. Окружения Codex, авторизация, проекты, история и работающие экземпляры сохранятся."], "uz-Latn": ["other": "Ushbu ro‘yxatdan {0} ta saqlangan hisob yozuvini olib tashlash. Faol profillar va ularning bog‘lanishlari o‘zgarmaydi.\n\nAvval metama’lumotning tekshirilgan zaxirasi yaratiladi. Codex muhitlari, kirish holati, loyihalar, tarix va ishlayotgan nusxalar saqlanadi."]],
        "message.a9a56b6644": ["en": ["other": "Codex detected: {0}"], "ru": ["other": "Codex найден: {0}"], "uz-Latn": ["other": "Codex topildi: {0}"]],
        "message.abb4a62b3a": ["en": ["other": "The operation was cancelled."], "ru": ["other": "Операция отменена."], "uz-Latn": ["other": "Amal bekor qilindi."]],
        "message.abc04aa349": ["en": ["other": "Choose the official application with bundle identifier com.openai.codex."], "ru": ["other": "Выберите официальное приложение с идентификатором com.openai.codex."], "uz-Latn": ["other": "com.openai.codex identifikatoriga ega rasmiy ilovani tanlang."]],
        "message.ae3e2b0895": ["en": ["other": "Another CodexSwoop process is updating profiles. Try again."], "ru": ["other": "Другой процесс CodexSwoop обновляет профили. Повторите позже."], "uz-Latn": ["other": "Boshqa CodexSwoop jarayoni profillarni yangilamoqda. Keyinroq urinib ko‘ring."]],
        "message.af3dfd842a": ["en": ["other": "The environment, process or window changed. Review it before trying again."], "ru": ["other": "Окружение, процесс или окно изменились. Проверьте их перед повтором."], "uz-Latn": ["other": "Muhit, jarayon yoki oyna o‘zgardi. Qayta urinishdan oldin tekshiring."]],
        "message.b3140d0e6e": ["en": ["other": "Closing the Standard External account requires explicit primary-account consent and an approved lifecycle adapter."], "ru": ["other": "Для закрытия Standard External нужны явное согласие на закрытие основного аккаунта и разрешённый lifecycle-адаптер."], "uz-Latn": ["other": "Standard External nusxasini yopish uchun asosiy hisobni yopishga aniq rozilik va ruxsat etilgan lifecycle adapteri kerak."]],
        "message.b41732cbc9": ["en": ["other": "Codex received the launch request, but its GUI and backend ownership could not be confirmed within 20 seconds. Use Check Result to observe it again without relaunching."], "ru": ["other": "Запрос запуска передан Codex, но принадлежность GUI и backend не подтверждена за 20 секунд. Используйте «Проверить результат» без повторного запуска."], "uz-Latn": ["other": "Ochish so‘rovi Codex ilovasiga yuborildi, lekin GUI va backend egaligi 20 soniyada tasdiqlanmadi. Qayta ochmasdan «Natijani tekshirish»dan foydalaning."]],
        "message.b802bd2f80": ["en": ["other": "Account mismatch"], "ru": ["other": "Аккаунт не совпадает"], "uz-Latn": ["other": "Hisob mos emas"]],
        "message.b9c00fd9e0": ["en": ["other": "Close Others & Open"], "ru": ["other": "Закрыть остальные и открыть"], "uz-Latn": ["other": "Boshqalarini yopib ochish"]],
        "message.baf25268c0": ["en": ["other": "An account setup operation needs review. Finish it or restore its verified metadata backup before continuing. No Codex data was changed."], "ru": ["other": "Нужна проверка операции настройки. Завершите её или восстановите проверенную копию метаданных. Данные Codex не менялись."], "uz-Latn": ["other": "Sozlash amalini tekshirish kerak. Uni tugating yoki tekshirilgan metama’lumot zaxirasini tiklang. Codex ma’lumotlari o‘zgarmadi."]],
        "message.bd13d1307f": ["en": ["other": "Local profiles: {0}"], "ru": ["other": "Локальных профилей: {0}"], "uz-Latn": ["other": "Mahalliy profillar: {0}"]],
        "message.be04b80336": ["en": ["other": "The target account could not be confirmed."], "ru": ["other": "Не удалось подтвердить целевой аккаунт."], "uz-Latn": ["other": "Tanlangan hisobni tasdiqlab bo‘lmadi."]],
        "message.c09bd6c0fb": ["en": ["other": "Environment metadata is damaged or unsupported. Existing files have been preserved."], "ru": ["other": "Метаданные окружения повреждены или не поддерживаются. Существующие файлы сохранены."], "uz-Latn": ["other": "Muhit metama’lumoti buzilgan yoki qo‘llab-quvvatlanmaydi. Mavjud fayllar saqlandi."]],
        "message.c15cdd6496": ["en": ["other": "The reference could not be checked. Nothing was changed."], "ru": ["other": "Не удалось проверить привязку. Изменений нет."], "uz-Latn": ["other": "Bog‘lanishni tekshirib bo‘lmadi. Hech narsa o‘zgarmadi."]],
        "message.c27e7f0170": ["en": ["other": "\n\nEnvironment: {0}\nCODEX_HOME: {1}\nElectron: {2}\n\nConfirm that this linked environment is intended for this profile. ChatGPT account identity remains technically unverified; Usage Monitoring stays blocked. Other instances remain open."], "ru": ["other": "\n\nОкружение: {0}\nCODEX_HOME: {1}\nElectron: {2}\n\nПодтвердите, что окружение предназначено для этого профиля. Identity аккаунта ChatGPT технически не подтверждена; мониторинг лимитов остаётся заблокированным. Остальные экземпляры останутся открытыми."], "uz-Latn": ["other": "\n\nMuhit: {0}\nCODEX_HOME: {1}\nElectron: {2}\n\nBu muhit shu profilga tegishli ekanini tasdiqlang. ChatGPT hisobi identity qiymati texnik tasdiqlanmagan; limit kuzatuvi bloklangan holda qoladi. Boshqa nusxalar ochiq qoladi."]],
        "message.c3ecb03a38": ["en": ["other": "Old saved environments stay on disk. Restore them explicitly from Settings → Accounts & Storage."], "ru": ["other": "Старые окружения сохраняются на диске. Восстановите их явно в Настройки → Аккаунты и хранилище."], "uz-Latn": ["other": "Eski muhitlar diskda saqlanadi. Ularni Sozlamalar → Hisoblar va saqlash orqali alohida tiklang."]],
        "message.c422428afb": ["en": ["other": "Launch official Codex using this environment's CODEX_HOME and Electron data directories."], "ru": ["other": "Запустить официальный Codex с CODEX_HOME и каталогом данных Electron этого окружения."], "uz-Latn": ["other": "Rasmiy Codex ilovasini shu muhitning CODEX_HOME va Electron ma’lumot papkalari bilan ochish."]],
        "message.c523467a88": ["en": ["other": "The setup journal or backup is inconsistent. Changes are blocked; existing files are preserved."], "ru": ["other": "Журнал настройки или копия несогласованы. Изменения заблокированы; файлы сохранены."], "uz-Latn": ["other": "Sozlash jurnali yoki zaxira mos emas. O‘zgarishlar bloklandi; fayllar saqlandi."]],
        "message.c6c3f80446": ["en": ["other": "0% left"], "ru": ["other": "Осталось 0%"], "uz-Latn": ["other": "0% qoldi"]],
        "message.c6e5a682a1": ["en": ["other": "Metadata status: readable"], "ru": ["other": "Состояние метаданных: доступны для чтения"], "uz-Latn": ["other": "Metama’lumot holati: o‘qish mumkin"]],
        "message.ca4dd4cbef": ["en": ["other": "Restore Saved Environment?"], "ru": ["other": "Восстановить сохранённое окружение?"], "uz-Latn": ["other": "Saqlangan muhit tiklansinmi?"]],
        "message.cb2ee77508": ["en": ["other": "Close other Codex instances and open this account"], "ru": ["other": "Закрыть остальные экземпляры Codex и открыть этот аккаунт"], "uz-Latn": ["other": "Boshqa Codex nusxalarini yopib, shu hisobni ochish"]],
        "message.cbdc541d36": ["en": ["other": "The environment is unavailable. Recheck its directories."], "ru": ["other": "Окружение недоступно. Проверьте его каталоги."], "uz-Latn": ["other": "Muhit mavjud emas. Uning papkalarini tekshiring."]],
        "message.cea499aadc": ["en": ["other": "Setup could not be saved. Review its state before trying again. Existing Codex files remain on disk."], "ru": ["other": "Не удалось сохранить настройку. Проверьте её состояние перед повтором. Файлы Codex остались на диске."], "uz-Latn": ["other": "Sozlashni saqlab bo‘lmadi. Qayta urinishdan oldin holatini tekshiring. Codex fayllari diskda qoldi."]],
        "message.cf04b8b855": ["en": ["other": "These profiles were saved by a newer app. Update CodexSwoop before editing."], "ru": ["other": "Профили сохранены более новой версией. Перед изменением обновите CodexSwoop."], "uz-Latn": ["other": "Profillar yangi versiyada saqlangan. O‘zgartirishdan oldin CodexSwoop ilovasini yangilang."]],
        "message.cfeaf63d44": ["en": ["other": "The target requires official authentication. No sign-in was started."], "ru": ["other": "Нужна официальная авторизация в целевом аккаунте. Вход не запускался."], "uz-Latn": ["other": "Tanlangan hisobga rasmiy kirish kerak. Kirish boshlanmadi."]],
        "message.d1e7d1ae9c": ["en": ["other": "Clear Saved Accounts"], "ru": ["other": "Очистить сохранённые аккаунты"], "uz-Latn": ["other": "Saqlangan hisoblarni tozalash"]],
        "message.d725b066a6": ["en": ["other": "Verification error"], "ru": ["other": "Ошибка проверки"], "uz-Latn": ["other": "Tekshiruv xatosi"]],
        "message.d7b589254c": ["en": ["other": "unbundled development build"], "ru": ["other": "сборка разработки без app bundle"], "uz-Latn": ["other": "app bundle bo‘lmagan ishlab chiqish yig‘ilmasi"]],
        "message.da7db9f601": ["en": ["other": "No verified usage snapshot yet."], "ru": ["other": "Подтверждённого снимка лимитов пока нет."], "uz-Latn": ["other": "Hozircha tasdiqlangan limit holati yo‘q."]],
        "message.dae991678d": ["en": ["other": "Confirm this profile's environment binding. ChatGPT identity is not technically verified by opening an environment; Usage keeps its independent checks."], "ru": ["other": "Подтвердите привязку окружения к профилю. Открытие окружения не подтверждает техническую identity ChatGPT; для лимитов действуют отдельные проверки."], "uz-Latn": ["other": "Muhitning profilga bog‘lanishini tasdiqlang. Muhitni ochish ChatGPT texnik identity qiymatini tasdiqlamaydi; limitlar uchun alohida tekshiruvlar amal qiladi."]],
        "message.daf4974f13": ["en": ["other": "Switching is unavailable until the integration safety gates pass."], "ru": ["other": "Переключение недоступно до прохождения проверок безопасности интеграции."], "uz-Latn": ["other": "Integratsiya xavfsizlik tekshiruvlari o‘tmaguncha almashish mavjud emas."]],
        "message.dc95ee0080": ["en": ["other": "A verified account and transport are required."], "ru": ["other": "Нужны подтверждённые аккаунт и соединение."], "uz-Latn": ["other": "Tasdiqlangan hisob va ulanish kerak."]],
        "message.dcd161ced4": ["en": ["other": "Cached values are outdated; refresh before relying on them."], "ru": ["other": "Кеш устарел; обновите данные перед использованием."], "uz-Latn": ["other": "Kesh eskirgan; foydalanishdan oldin yangilang."]],
        "message.dd25f0255a": ["en": ["other": "Account verification failed. No account details were logged."], "ru": ["other": "Проверка аккаунта не удалась. Данные аккаунта не записывались в журнал."], "uz-Latn": ["other": "Hisob tekshiruvi bajarilmadi. Hisob ma’lumotlari jurnalga yozilmadi."]],
        "message.e4107a4e39": ["en": ["other": "This protocol version has not been reviewed."], "ru": ["other": "Эта версия протокола не проверена."], "uz-Latn": ["other": "Bu protokol versiyasi tekshirilmagan."]],
        "message.e567a39ada": ["en": ["other": "Quota remaining. Last successful update below."], "ru": ["other": "Оставшийся лимит. Последнее успешное обновление ниже."], "uz-Latn": ["other": "Qolgan limit. Oxirgi muvaffaqiyatli yangilanish quyida."]],
        "message.e6288862ea": ["en": ["other": "Check which instances remain open and any unsaved work. A previous request may have taken effect. Confirm only after reviewing Codex. This clears the operation warning; the next action will run fresh checks and ask for confirmation."], "ru": ["other": "Проверьте открытые экземпляры и несохранённую работу. Предыдущий запрос мог выполниться. Подтвердите только после проверки Codex. Затем будут выполнены свежие проверки состояния; следующая операция потребует нового подтверждения."], "uz-Latn": ["other": "Ochiq nusxalar va saqlanmagan ishlarni tekshiring. Oldingi so‘rov bajarilgan bo‘lishi mumkin. Faqat Codex tekshirilgach tasdiqlang. Keyin holat qayta tekshiriladi; keyingi amal yangi tasdiq talab qiladi."]],
        "message.ea89d4c0ad": ["en": ["other": "Confirm this operation before continuing."], "ru": ["other": "Подтвердите эту операцию перед продолжением."], "uz-Latn": ["other": "Davom etishdan oldin bu amalni tasdiqlang."]],
        "message.ec5942ca5b": ["en": ["other": "Checking the source and fetching usage…"], "ru": ["other": "Проверка источника и получение лимитов…"], "uz-Latn": ["other": "Manba tekshirilmoqda va limitlar olinmoqda…"]],
        "message.ecdf29e1bb": ["en": ["other": "Open Separately · {0}?"], "ru": ["other": "Открыть отдельно · {0}?"], "uz-Latn": ["other": "Alohida ochish · {0}?"]],
        "message.ecfea25ef6": ["en": ["other": "NO-GO: metadata changed. Prepare and review a new preview."], "ru": ["other": "NO-GO: метаданные изменились. Подготовьте и проверьте новый предварительный результат."], "uz-Latn": ["other": "NO-GO: metama’lumot o‘zgardi. Yangi oldindan ko‘rish natijasini tayyorlab tekshiring."]],
        "message.ee301ab0fc": ["en": ["other": "Directories still match. Environment opening requires fresh process checks; ChatGPT identity remains unverified."], "ru": ["other": "Каталоги совпадают. Для открытия нужны свежие проверки процессов; identity ChatGPT не подтверждена."], "uz-Latn": ["other": "Papkalar mos. Ochish uchun jarayonlar qayta tekshiriladi; ChatGPT identity qiymati tasdiqlanmagan."]],
        "message.ee90487fb2": ["en": ["other": "The operation stopped."], "ru": ["other": "Операция остановлена."], "uz-Latn": ["other": "Amal to‘xtatildi."]],
        "message.ee986a6259": ["en": ["other": "Link an existing environment reference. This does not sign in, close Codex or confirm account identity."], "ru": ["other": "Привязать существующее окружение. Без входа, закрытия Codex и подтверждения identity аккаунта."], "uz-Latn": ["other": "Mavjud muhitni bog‘lash. Kirish, Codex ilovasini yopish yoki hisob identity tasdig‘i bajarilmaydi."]],
        "message.eea70ce79c": ["en": ["other": "100% left"], "ru": ["other": "Осталось 100%"], "uz-Latn": ["other": "100% qoldi"]],
        "message.ef191576ee": ["en": ["other": "{0} · PID {1} · Activity: {2}{3}"], "ru": ["other": "{0} · PID {1} · Активность: {2}{3}"], "uz-Latn": ["other": "{0} · PID {1} · Faollik: {2}{3}"]],
        "message.f04d8455dd": ["en": ["other": "Invalid name"], "ru": ["other": "Недопустимое название"], "uz-Latn": ["other": "Noto‘g‘ri nom"]],
        "message.f0d7f42301": ["en": ["other": "Open Environment · {0}?"], "ru": ["other": "Открыть окружение · {0}?"], "uz-Latn": ["other": "Muhitni ochish · {0}?"]],
        "message.f103e3036e": ["en": ["other": "Refresh is temporarily rate limited."], "ru": ["other": "Обновление временно ограничено числом запросов."], "uz-Latn": ["other": "Yangilash so‘rovlar soni sabab vaqtincha cheklangan."]],
        "message.f1d0272f0e": ["en": ["other": "Choose Existing Codex Environment"], "ru": ["other": "Выбрать существующее окружение Codex"], "uz-Latn": ["other": "Mavjud Codex muhitini tanlash"]],
        "message.f37361768d": ["en": ["other": "Restore Previous Setup"], "ru": ["other": "Восстановить предыдущую настройку"], "uz-Latn": ["other": "Oldingi sozlashni tiklash"]],
        "message.f3a93ef749": ["en": ["other": "Only permanent Managed and Standard External environments can be opened."], "ru": ["other": "Можно открывать только постоянные Managed и Standard External окружения."], "uz-Latn": ["other": "Faqat doimiy Managed va Standard External muhitlarni ochish mumkin."]],
        "message.f5f53660b0": ["en": ["other": "Your profile ID and local directory stay the same."], "ru": ["other": "ID профиля и локальный каталог сохраняются."], "uz-Latn": ["other": "Profil ID qiymati va mahalliy papka saqlanadi."]],
        "message.f8268d31fc": ["en": ["other": "Restore Environment"], "ru": ["other": "Восстановить окружение"], "uz-Latn": ["other": "Muhitni tiklash"]],
        "message.f8baba2ae8": ["en": ["other": "\n\nConfirm that this linked environment is intended for this profile."], "ru": ["other": "\n\nПодтвердите, что привязанное окружение предназначено для этого профиля."], "uz-Latn": ["other": "\n\nBog‘langan muhit shu profilga mo‘ljallanganini tasdiqlang."]],
        "message.f9b461fcfb": ["en": ["other": "Restore {0} with its original UUID {1}.\n\nCODEX_HOME: {2}\nElectron data: {3}\n\nOnly profile metadata and the link will be restored. Authorization files stay in place. Codex will not be opened automatically."], "ru": ["other": "Восстановить {0} с исходным UUID {1}.\n\nCODEX_HOME: {2}\nДанные Electron: {3}\n\nВосстановятся только метаданные профиля и привязка. Файлы авторизации останутся на месте. Codex автоматически не откроется."], "uz-Latn": ["other": "{0} muhitini asl UUID {1} bilan tiklash.\n\nCODEX_HOME: {2}\nElectron ma’lumotlari: {3}\n\nFaqat profil metama’lumoti va bog‘lanishi tiklanadi. Kirish fayllari joyida qoladi. Codex avtomatik ochilmaydi."]],
        "message.fa0fc3a9fe": ["en": ["other": "Unknown window"], "ru": ["other": "Неизвестный интервал"], "uz-Latn": ["other": "Noma’lum davr"]],
        "message.faf2e32a37": ["en": ["other": "The launch failed. No automatic retry was attempted."], "ru": ["other": "Запуск не удался. Автоматический повтор не выполнялся."], "uz-Latn": ["other": "Ochish bajarilmadi. Avtomatik qayta urinish bajarilmadi."]],
        "message.fc25a80dbe": ["en": ["other": "Target CODEX_HOME: {0}\nTarget Electron data: {1}"], "ru": ["other": "Целевой CODEX_HOME: {0}\nДанные Electron: {1}"], "uz-Latn": ["other": "Maqsad CODEX_HOME: {0}\nElectron ma’lumotlari: {1}"]],
        "message.fd203e3b54": ["en": ["other": "Environment metadata requires a newer CodexSwoop version. It cannot be edited or recovered over."], "ru": ["other": "Для этих метаданных нужна новая версия CodexSwoop. Изменение и восстановление поверх них запрещены."], "uz-Latn": ["other": "Bu metama’lumot uchun yangi CodexSwoop versiyasi kerak. Uni o‘zgartirish yoki ustidan tiklash taqiqlangan."]],
        "message.ffc6526840": ["en": ["other": "Import Current Account links the standard locations only. The running app may use other settings; identity remains Verification required."], "ru": ["other": "Подключаются только стандартные каталоги. Работающее приложение может использовать другие настройки; identity требует проверки."], "uz-Latn": ["other": "Faqat standart papkalar bog‘lanadi. Ishlayotgan ilova boshqa sozlamalardan foydalanishi mumkin; identity tekshirilishi kerak."]],
        "onboarding.actionFailed": ["en": ["other": "We couldn't complete this action. Check Details before trying again."], "ru": ["other": "Не удалось завершить действие. Перед новой попыткой откройте подробности."], "uz-Latn": ["other": "Amalni yakunlab bo‘lmadi. Qayta urinishdan oldin tafsilotlarni ko‘ring."]],
        "onboarding.addHint": ["en": ["other": "Use an existing Codex account or sign in to another one."], "ru": ["other": "Подключите существующий аккаунт Codex или войдите в другой."], "uz-Latn": ["other": "Mavjud Codex hisobini ulang yoki boshqa hisobga kiring."]],
        "onboarding.axWindowExplanation": ["en": ["other": "Accessibility is needed only to inspect or focus a specific confirmed window. Permission alone cannot confirm which account owns it. Opening an account by its verified process does not need this permission."], "ru": ["other": "Универсальный доступ нужен только для проверки или фокусировки конкретного подтверждённого окна. Само разрешение не подтверждает аккаунт в нём. Открытие аккаунта через проверенный процесс работает без этого разрешения."], "uz-Latn": ["other": "Maxsus imkoniyatlar faqat tasdiqlangan alohida oynani tekshirish yoki unga fokus berish uchun kerak. Ruxsatning o‘zi oynadagi hisobni tasdiqlamaydi. Hisobni tekshirilgan jarayon orqali ochishga bu ruxsat kerak emas."]],
        "onboarding.checkAgain": ["en": ["other": "Check Again"], "ru": ["other": "Проверить ещё раз"], "uz-Latn": ["other": "Qayta tekshirish"]],
        "onboarding.checkStatus": ["en": ["other": "Check Status"], "ru": ["other": "Проверить статус"], "uz-Latn": ["other": "Holatni tekshirish"]],
        "onboarding.closeWindow": ["en": ["other": "Close Window"], "ru": ["other": "Закрыть окно"], "uz-Latn": ["other": "Oynani yopish"]],
        "onboarding.codex.checking": ["en": ["other": "Verifying the official Codex installation…"], "ru": ["other": "Проверяем официальную установку Codex…"], "uz-Latn": ["other": "Rasmiy Codex o‘rnatmasi tekshirilmoqda…"]],
        "onboarding.codex.lastTested": ["en": ["other": "Last individually tested Codex version: {0}."], "ru": ["other": "Последняя отдельно протестированная версия Codex: {0}."], "uz-Latn": ["other": "Alohida sinovdan o‘tkazilgan so‘nggi Codex versiyasi: {0}."]],
        "onboarding.codex.missing": ["en": ["other": "Codex Desktop was not found on this Mac."], "ru": ["other": "Codex Desktop не найден на этом Mac."], "uz-Latn": ["other": "Bu Mac’da Codex Desktop topilmadi."]],
        "onboarding.codex.statusUnverified": ["en": ["other": "Installation not verified"], "ru": ["other": "Установка не проверена"], "uz-Latn": ["other": "O‘rnatma tasdiqlanmagan"]],
        "onboarding.codex.untested": ["en": ["other": "Codex {0} detected. This version has not been individually tested with CodexSwoop."], "ru": ["other": "Обнаружен Codex {0}. Эта версия отдельно не тестировалась с CodexSwoop."], "uz-Latn": ["other": "Codex {0} aniqlandi. Bu versiya CodexSwoop bilan alohida sinovdan o‘tkazilmagan."]],
        "onboarding.codex.unverified": ["en": ["other": "The official Codex installation could not be verified. Opening is unavailable; local profiles can still be managed."], "ru": ["other": "Не удалось проверить официальную установку Codex. Открытие недоступно; локальными профилями можно управлять."], "uz-Latn": ["other": "Rasmiy Codex o‘rnatmasini tekshirib bo‘lmadi. Ochish mavjud emas; mahalliy profillarni boshqarish mumkin."]],
