        "onboarding.windowFeatures": ["en": ["other": "About window-specific features"], "ru": ["other": "О работе с отдельными окнами"], "uz-Latn": ["other": "Alohida oynalar haqida"]],
        "onboarding.windowUncertain": ["en": ["other": "We couldn't confirm which Codex window belongs to this account."], "ru": ["other": "Не удалось подтвердить, какое окно Codex принадлежит этому аккаунту."], "uz-Latn": ["other": "Qaysi Codex oynasi ushbu hisobga tegishli ekanini tasdiqlab bo‘lmadi."]],
        "opening.activated": ["en": ["other": "The selected Codex instance is in the foreground. ChatGPT identity remains unverified."], "ru": ["other": "Выбранный экземпляр Codex на переднем плане. Identity ChatGPT не подтверждена."], "uz-Latn": ["other": "Tanlangan Codex nusxasi oldingi planda. ChatGPT identity qiymati tasdiqlanmagan."]],
        "opening.blocked": ["en": ["other": "Switching requires verified account identity and controlled two-account acceptance. Linking an environment does not enable switching."], "ru": ["other": "Для переключения нужны подтверждённая identity и испытание с двумя аккаунтами. Привязка окружения не включает переключение."], "uz-Latn": ["other": "Almashish uchun tasdiqlangan identity va ikki hisob bilan nazoratli sinov kerak. Muhitni bog‘lash almashishni yoqmaydi."]],
        "opening.launched": ["en": ["other": "Codex opened with the linked environment and is in the foreground. ChatGPT identity remains unverified."], "ru": ["other": "Codex открыт с привязанным окружением и находится на переднем плане. Identity ChatGPT не подтверждена."], "uz-Latn": ["other": "Codex bog‘langan muhit bilan ochildi va oldingi planda. ChatGPT identity qiymati tasdiqlanmagan."]],
        "opening.noResult": ["en": ["other": "The operation has no confirmed result. Check Codex."], "ru": ["other": "Результат операции не подтверждён. Проверьте Codex."], "uz-Latn": ["other": "Amal natijasi tasdiqlanmadi. Codex ilovasini tekshiring."]],
        "review.bootChanged": ["en": ["other": "The recorded opening belongs to another Mac boot session. Process disappearance does not prove the historical result. Preserve the journal and agree a separate recovery procedure."], "ru": ["other": "Записанное открытие относится к другой загрузочной сессии Mac. Исчезновение процессов не доказывает исторический результат. Сохраните журнал и отдельно согласуйте процедуру восстановления."], "uz-Latn": ["other": "Yozilgan ochish boshqa Mac yuklanish seansiga tegishli. Jarayonlar yo‘qligi oldingi natijani isbotlamaydi. Jurnalni saqlang va alohida tiklash tartibini kelishing."]],
        "review.check": ["en": ["other": "Check Again"], "ru": ["other": "Проверить ещё раз"], "uz-Latn": ["other": "Qayta tekshirish"]],
        "review.detail": ["en": ["other": "Review Codex and any unsaved work. This performs read-only checks of current processes, signature and environment ownership. It never launches or closes Codex. If ownership remains unknown, the warning stays."], "ru": ["other": "Проверьте Codex и несохранённую работу. Будут только прочитаны текущие процессы, подпись и принадлежность окружений. Codex не запускается и не закрывается. При неизвестной принадлежности предупреждение сохранится."], "uz-Latn": ["other": "Codex va saqlanmagan ishlarni ko‘rib chiqing. Faqat joriy jarayonlar, imzo va muhit egaligi tekshiriladi. Codex ochilmaydi va yopilmaydi. Egalik noma’lum qolsa, ogohlantirish saqlanadi."]],
        "review.journalBusy": ["en": ["other": "Another process holds the opening or metadata lock. No recovery result is available until that owner releases it."], "ru": ["other": "Другой процесс удерживает блокировку opening или metadata. Результат проверки недоступен до освобождения блокировки владельцем."], "uz-Latn": ["other": "Boshqa jarayon ochish yoki metama’lumot qulfini ushlab turibdi. Egasi qulfni bo‘shatmaguncha tekshiruv natijasi mavjud emas."]],
        "review.journalConflict": ["en": ["other": "An unfinished opening or changed metadata conflicts with this action. Preserve the journal; Check Again must verify the recorded operation before another action."], "ru": ["other": "Незавершённое открытие или изменённые metadata конфликтуют с действием. Сохраните журнал; перед следующим действием «Проверить ещё раз» должно проверить записанную операцию."], "uz-Latn": ["other": "Tugallanmagan ochish yoki o‘zgargan metama’lumot bu amalga zid. Jurnalni saqlang; yangi amaldan oldin yozilgan amalni qayta tekshirish kerak."]],
        "review.journalDetail": ["en": ["other": "The opening journal needs review. Invalid or unsupported records, changed metadata, another running operation, or a different Mac boot session block new actions. Check Again only observes processes; it never launches or closes Codex. A missing journal or watermark in an initialized store requires investigation; older stores need a separately reviewed bootstrap."], "ru": ["other": "Журнал открытия требует проверки. Повреждённая или неподдерживаемая запись, изменённые метаданные, другая выполняемая операция или новая загрузочная сессия Mac блокируют новые действия. «Проверить ещё раз» только наблюдает процессы, не запуская и не закрывая Codex. Отсутствие журнала или watermark в инициализированном хранилище требует расследования; для старого хранилища нужна отдельно согласованная инициализация."], "uz-Latn": ["other": "Ochish jurnalini tekshirish kerak. Buzilgan yoki qo‘llab-quvvatlanmaydigan yozuvlar, o‘zgargan metama’lumot, boshqa bajarilayotgan amal yoki Mac qayta yuklangani yangi amallarni to‘sadi. Qayta tekshirish faqat jarayonlarni kuzatadi; Codex ilovasini ochmaydi va yopmaydi. Tayyorlangan omborda jurnal yoki watermark yo‘qligi tekshiruvni talab qiladi; eski ombor uchun alohida kelishilgan boshlang‘ich sozlash kerak."]],
        "review.journalInvalid": ["en": ["other": "The opening journal and watermark are invalid, unsupported, or inconsistent. Keep both files and backups; automatic repair is blocked. Restore only an independently verified matching pair after a separate review."], "ru": ["other": "Журнал открытия и watermark повреждены, несовместимы или несогласованы. Сохраните оба файла и резервные копии; автоматическое исправление заблокировано. Восстановление независимо проверенной согласованной пары требует отдельного согласования."], "uz-Latn": ["other": "Ochish jurnali va watermark buzilgan, mos emas yoki nomuvofiq. Ikkala fayl va zaxiralarni saqlang; avtomatik tuzatish bloklangan. Tekshirilgan mos juftlikni tiklash uchun alohida kelishuv kerak."]],
        "review.journalLegacy": ["en": ["other": "This existing metadata store has no opening journal or watermark. It is a legacy store, not a clean installation. Bootstrap requires separate consent, a verified catalog snapshot, and review of unresolved older operations."], "ru": ["other": "У существующего хранилища metadata отсутствуют журнал открытия и watermark. Это legacy-хранилище, а не чистая установка. Инициализация требует отдельного согласия, проверки снимка каталогов и незавершённых старых операций."], "uz-Latn": ["other": "Mavjud metama’lumot omborida ochish jurnali va watermark yo‘q. Bu yangi o‘rnatish emas, eski ombor. Boshlang‘ich sozlash uchun alohida rozilik, katalog nusxasi va eski tugallanmagan amallar tekshiruvi kerak."]],
        "review.journalUnavailable": ["en": ["other": "The opening journal or its metadata lock cannot be accessed. Check storage ownership and permissions without changing journal evidence."], "ru": ["other": "Журнал открытия или блокировка metadata недоступны. Проверьте владельца и права хранилища, сохранив записи журнала."], "uz-Latn": ["other": "Ochish jurnali yoki metama’lumot qulfi ochilmadi. Jurnal dalillarini saqlagan holda ombor egasi va ruxsatlarini tekshiring."]],
        "review.pendingDetail": ["en": ["other": "A recorded unfinished opening blocks new actions. Check Again verifies current process ownership without launching or closing Codex. If proof fails, Details keeps the specific reason; dismissing a message never settles the journal."], "ru": ["other": "Новые действия блокирует записанная незавершённая операция открытия. «Проверить ещё раз» проверяет текущую принадлежность процессов без запуска или закрытия Codex. Если доказательств недостаточно, в подробностях сохраняется конкретная причина; закрытие сообщения не завершает журнал."], "uz-Latn": ["other": "Yozilgan tugallanmagan ochish yangi amallarni to‘sadi. Qayta tekshirish Codex ilovasini ochmasdan yoki yopmasdan joriy jarayon egaligini tekshiradi. Dalil yetmasa, aniq sabab tafsilotlarda saqlanadi; xabarni yopish jurnalni yakunlamaydi."]],
        "review.previousOperation": ["en": ["other": "Previous operation needs review."], "ru": ["other": "Предыдущая операция требует проверки."], "uz-Latn": ["other": "Oldingi amalni tekshirish kerak."]],
        "review.requiredDetail": ["en": ["other": "A previous action may have finished only partly. Check Again safely checks the current state before another action."], "ru": ["other": "Предыдущее действие могло завершиться частично. «Проверить ещё раз» безопасно проверит состояние перед новой операцией."], "uz-Latn": ["other": "Oldingi amal qisman tugagan bo‘lishi mumkin. Qayta tekshirish keyingi amaldan oldin joriy holatni xavfsiz tekshiradi."]],
        "review.resolved": ["en": ["other": "Ready for a new operation."], "ru": ["other": "Можно начать новую операцию."], "uz-Latn": ["other": "Yangi amalni boshlash mumkin."]],
        "review.safeDetail": ["en": ["other": "Current process and environment ownership was checked. Starting a new operation is safe. This does not confirm that the previous window activation succeeded or verify the ChatGPT account."], "ru": ["other": "Проверена текущая принадлежность процессов и окружений. Можно безопасно начать новую операцию. Успех предыдущей активации окна и личность аккаунта ChatGPT не подтверждены."], "uz-Latn": ["other": "Joriy jarayonlar va muhit egaligi tekshirildi. Yangi amalni xavfsiz boshlash mumkin. Bu oldingi oyna faollashgani yoki ChatGPT hisobi shaxsini tasdiqlamaydi."]],
        "review.targetChanged": ["en": ["other": "The recorded target process generation no longer matches the current environment. Historical activation is unproven. The pending record is preserved; a separately agreed recovery procedure is required before new operations."], "ru": ["other": "Записанное поколение целевого процесса больше не совпадает с текущим окружением. Историческая активация не доказана. Pending-запись сохранена; перед новыми операциями нужна отдельно согласованная процедура восстановления."], "uz-Latn": ["other": "Yozilgan nishon jarayon avlodi joriy muhitga mos kelmaydi. Oldingi faollashtirish isbotlanmagan. Tugallanmagan yozuv saqlanadi; yangi amallardan oldin alohida kelishilgan tiklash tartibi kerak."]],
        "review.title": ["en": ["other": "Check previous result?"], "ru": ["other": "Проверить предыдущий результат?"], "uz-Latn": ["other": "Oldingi natija tekshirilsinmi?"]],
        "settings.about": ["en": ["other": "Independent utility. Not affiliated with OpenAI."], "ru": ["other": "Независимая утилита. Не связана с OpenAI."], "uz-Latn": ["other": "Mustaqil yordamchi ilova. OpenAI bilan bog‘liq emas."]],
